// Importing necessary modules and components
import React, { useState, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import { Link } from 'react-router-dom';
import { Formik, Form, Field, ErrorMessage } from 'formik';
import * as yup from 'yup';
import axios from 'axios';
import AuthContext from '../Components/AuthContext';
import '../CSS/login.css';

// Defining the SignUp component
function SignUp() {

  const [errorMessage, setErrorMessage] = useState('');
  const [successMessage, setSuccessMessage] = useState('');
  const navigate = useNavigate();
  const { fetchUserData } = useContext(AuthContext);

 
  const signUpSchema = yup.object().shape({
    email: yup.string().email('Invalid email address').required('Email is required'),
    password: yup.string().min(6, 'Password must be at least 6 characters').required('Password is required'),
    username: yup.string().min(3, 'Username must be at least 3 characters').required('Username is required'),
  });

  const handleSubmit = async (values) => {
    try {
      const response = await axios.post('http://localhost:3001/signup', values);
      // Sign up was successful
      const token = response.data.token;
      // Storing the token in local storage with 'token' as key
      localStorage.setItem('token', token);
      // Calling fetchUserData function with token as argument
      fetchUserData(token);

      // Updating the successMessage state variable with an appropriate message
      setSuccessMessage('Sign up successful! Redirecting to home page...');

      // Navigating to the home page after a delay
      setTimeout(() => {
        navigate('/');
      }, 1000);
    } catch (error) {
      // Sign up failed
      setErrorMessage(error.response.data.error || 'An error occurred. Please try again.');
    }
  };

  // Rendering the sign-up form with formik and yup using async/await syntax
  return (
    <div className="login-container">
      <div className="login-form">
        <h1>Sign Up to MovieMate</h1>
        {errorMessage && <p>{errorMessage}</p>}
        {successMessage && <p>{successMessage}</p>}
        <Formik
          initialValues={{ email: '', password: '', username: '' }}
          validationSchema={signUpSchema}
          onSubmit={handleSubmit}
        >
          {({ errors, touched }) => (
            <Form>
              <label htmlFor="email">Email:</label>
              <Field className="form-input" type="email" id="email" name="email" />
              <ErrorMessage name="email" component="p" />
              <br />
              <label htmlFor="password">Password:</label>
              <Field className="form-input" type="password" id="password" name="password" />
              <ErrorMessage name="password" component="p" />
              <br />
              <label htmlFor="username">Username:</label>
              <Field className="form-input" type="text" id="username" name="username" />
              <ErrorMessage name="username" component="p" />
              <br />
              <button className='form-button' type="submit">Sign Up</button>
            </Form>
          )}
        </Formik>
        <p>
          Already have an account?{' '}
          <Link to="/login">Sign in</Link>
        </p>
      </div>
    </div>
  );
}

// Exporting the SignUp component as the default export
export default SignUp;

